  CREATE PROCEDURE [bud].[jsApproveBudgetAllocationRequest]      @flowId INT = 5,      @company INT = 1,      @userId INT = 68,      @remarks NVARCHAR(MAX) = 'OK',      @action NVARCHAR(20) = 'Approve'  AS  BEGIN      SET NOCOUNT ON;        DECLARE @Message NVARCHAR(4000)        BEGIN TRY          BEGIN TRANSACTION            DECLARE @templateId INT,                  @totalStages INT,                  @currentStage INT,                  @currentStageId INT,                  @previousStage INT,                  @previousStageId INT,                  @approvalRequired INT,                  @approvedCount INT,                  @existingStatus NVARCHAR(50) = 'None',                  @currentStageActions INT,                  @userStage INT,                  @userStageId INT,                  @nextStageId INT,                  @currentDocStatus NVARCHAR(10),                  @budgetAllocationRequestId INT,                  @docCompany INT            -- Get Budget Allocation Request Flow details          SELECT               @templateId = bf.templateId,              @totalStages = bf.totalStage,              @currentStage = bf.currentStage,              @budgetAllocationRequestId = bf.budgetAllocationRequestId          FROM bud.jsFlow bf          WHERE bf.id = @flowId            IF @templateId IS NULL              THROW 50001, 'Budget Allocation Request workflow not found with the specified parameters', 1            -- Get company from BudgetAllocationRequest -> BudgetMonthlyAllocations -> Budgets          SELECT @docCompany = b.company          FROM bud.BudgetAllocationRequest bar          INNER JOIN bud.BudgetMonthlyAllocations bma ON bar.budgetAllocationId = bma.allocationId          INNER JOIN bud.Budgets b ON bma.budgetId = b.budgetId          WHERE bar.id = @budgetAllocationRequestId            -- Validate company          IF @docCompany != @company              THROW 50003, 'Access denied: Budget Allocation Request belongs to a different company', 1            -- Get current and previous stage IDs          SELECT @currentStageId = stageId          FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @currentStage            SET @previousStage = @currentStage - 1            SELECT @previousStageId = stageId          FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @previousStage            -- Determine user's stage          SELECT TOP 1 @userStage = jst.priority, @userStageId = jst.stageId          FROM jsUserStage us          JOIN jsStageTemplate jst ON us.stageId = jst.stageId          WHERE us.userId = @userId            AND jst.templateId = @templateId          ORDER BY jst.priority            IF @userStage IS NULL              THROW 50002, 'User is not assigned to any stage in this Budget Allocation Request workflow', 1            -- Count actions in current stage          SELECT @currentStageActions = COUNT(*)          FROM bud.jsFlowStatus          WHERE flowId = @flowId            AND stageId = @currentStageId            -- APPROVE LOGIC          IF @action = 'Approve'          BEGIN              -- Check authorization              IF NOT EXISTS (                  SELECT 1                  FROM jsStageTemplate                  WHERE templateId = @templateId                    AND (stageId = @currentStageId OR (@currentStageActions = 0 AND stageId = @previousStageId))                    AND EXISTS (SELECT 1 FROM jsUserStage WHERE stageId = jsStageTemplate.stageId AND userId = @userId)              )                  THROW 50006, 'User is not authorized to approve this Budget Allocation Request.', 1                -- Existing status              SELECT TOP 1 @existingStatus = status              FROM bud.jsFlowStatus              WHERE flowId = @flowId                AND stageId = @userStageId                AND userId = @userId              ORDER BY createdOn DESC                -- Prevent duplicate approvals              IF @existingStatus = 'A' AND @userStage = @currentStage                  THROW 50020, 'User has already approved this Budget Allocation Request.', 1                -- Insert or update approval              IF @existingStatus IS NULL OR @existingStatus = 'None'              BEGIN                  INSERT INTO bud.jsFlowStatus                      (flowId, status, stageId, templateId, userId, createdOn, description)                  VALUES                      (@flowId, 'A', @userStageId, @templateId, @userId, SYSUTCDATETIME(), @remarks)              END              ELSE              BEGIN                  UPDATE bud.jsFlowStatus                  SET status = 'A',                      description = @remarks,                      createdOn = SYSUTCDATETIME()                  WHERE flowId = @flowId                    AND stageId = @userStageId                    AND userId = @userId              END                -- Count approvals in current stage              SELECT @approvedCount = COUNT(*)              FROM bud.jsFlowStatus              WHERE flowId = @flowId                AND stageId = @currentStageId                AND status = 'A'                -- Get approvals required              SELECT @approvalRequired = approval              FROM jsStage s              JOIN jsApprovalCount ac ON s.approvalId = ac.id              WHERE s.id = @currentStageId                -- Move stage or finalize              IF @approvedCount >= @approvalRequired              BEGIN                  IF @currentStage = @totalStages                  BEGIN                      UPDATE bud.jsFlow                      SET status = 'A', updatedOn = SYSUTCDATETIME()                      WHERE id = @flowId                        -- Update the allocated amount in BudgetMonthlyAllocations                      UPDATE bma                      SET bma.allocatedAmount = bma.allocatedAmount + bar.newAmount,                          bma.updatedAt = GETDATE()                      FROM bud.BudgetMonthlyAllocations bma                      INNER JOIN bud.BudgetAllocationRequest bar ON bma.allocationId = bar.budgetAllocationId                      WHERE bar.id = @budgetAllocationRequestId                        SET @Message = 'Budget Allocation Request approved and finalized. Allocated amount updated.'                  END                  ELSE                  BEGIN                      DECLARE @nextStage INT = @currentStage + 1                        SELECT @nextStageId = stageId                      FROM jsStageTemplate                      WHERE templateId = @templateId AND priority = @nextStage                        UPDATE bud.jsFlow                      SET currentStage = @nextStage,                          currentStageId = @nextStageId,                          updatedOn = SYSUTCDATETIME()                      WHERE id = @flowId                        SET @Message = 'Budget Allocation Request moved to next stage'                  END              END              ELSE              BEGIN                  SET @Message = 'Not enough approvals to move to next stage'              END          END          -- REJECT LOGIC          ELSE IF @action = 'Reject'          BEGIN              -- Authorization check              IF NOT EXISTS (                  SELECT 1                  FROM jsStageTemplate                  WHERE templateId = @templateId                    AND (stageId = @currentStageId OR (@currentStageActions = 0 AND stageId = @previousStageId))                    AND EXISTS (SELECT 1 FROM jsUserStage WHERE stageId = jsStageTemplate.stageId AND userId = @userId)              )                  THROW 50011, 'User is not authorized to reject this Budget Allocation Request.', 1                -- Insert rejection              INSERT INTO bud.jsFlowStatus                  (flowId, status, stageId, templateId, userId, createdOn, description)              VALUES                  (@flowId, 'R', @userStageId, @templateId, @userId, SYSUTCDATETIME(), @remarks)                UPDATE bud.jsFlow              SET status = 'R', updatedOn = SYSUTCDATETIME()              WHERE id = @flowId                SET @Message = 'Budget Allocation Request rejected successfully'          END          ELSE              THROW 50009, 'Invalid action specified. Use "Approve", "Reject"', 1            COMMIT TRANSACTION            -- Return message and request info          SELECT               @Message AS ResultMessage,               @budgetAllocationRequestId AS BudgetAllocationRequestId,               @docCompany AS CompanyId,              @flowId AS FlowId        END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION            DECLARE @ErrorMessage NVARCHAR(4000),                  @ErrorSeverity INT,                  @ErrorState INT            SELECT               @ErrorMessage = ERROR_MESSAGE(),              @ErrorSeverity = ERROR_SEVERITY(),              @ErrorState = ERROR_STATE()            RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState)      END CATCH  END
